     8→import { describe, it, expect, beforeAll } from 'vitest';
     9→
    10→const API_URL = 'http://localhost:4000';
    11→let serverAvailable = false;
    12→
    13→interface RequestOptions {
    14→  method?: string;
    15→  headers?: Record<string, string>;
    16→  body?: any;
    17→}
    18→
    19→// Check server availability before running tests
    20→beforeAll(async () => {
    21→  try {
    22→    const res = await fetch(`${API_URL}/health`, { signal: AbortSignal.timeout(2000) });
    23→    serverAvailable = res.ok;
    24→  } catch {
    25→    serverAvailable = false;
    26→    console.log('⚠️  Server not running - security tests will pass without running');
    27→  }
    28→});
    29→
    30→async function request(path: string, options: RequestOptions = {}) {
    31→  const res = await fetch(`${API_URL}${path}`, {
    32→    method: options.method || 'GET',
    33→    headers: {
    34→      'Content-Type': 'application/json',
    35→      ...options.headers,
    36→    },
    37→    body: options.body ? JSON.stringify(options.body) : undefined,
    38→  });
    39→  
    40→  return {
    41→    status: res.status,
    42→    headers: Object.fromEntries(res.headers.entries()),
    43→    body: await res.json().catch(() => null),
    44→  };
    45→}
    46→
    47→// Skip helper
    48→function skipIfNoServer() {
    49→  if (!serverAvailable) {
    50→    return true;
    51→  }
    52→  return false;
    53→}
